function prop(item, name) {
  const p = item.json.properties?.[name];
  if (!p) return item.json[name] ?? '';
  if (p.type === 'title') return (p.title || []).map(v => v.plain_text || '').join('');
  if (p.type === 'rich_text') return (p.rich_text || []).map(v => v.plain_text || '').join('');
  if (p.type === 'select') return p.select?.name || '';
  if (p.type === 'date') return p.date?.start || '';
  if (p.type === 'number') return p.number || '';
  if (p.type === 'phone_number') return p.phone_number || '';
  if (p.type === 'relation') return (p.relation || []).map(v => v.id).join(',');
  return item.json[name] ?? '';
}
